// jtag12_io.v - 11 JTAG port groups (G2..G12; G1 driven by jtag_master) (TCK/TMS/TDI/TDO) -> AX7Z020B expansion header J20/J21
//
// Pin assignment: docs/JTAG12_J20_J21.md / vivado/constraints/jtag12.xdc
// (per AX7Z020B board user manual V1.0, section 2.17, tables 2.17.1 / 2.17.2)
//
// This is a **pin placeholder + scope self-test** module, not a TAP engine:
//   - TCK is generated by dividing clk (clk/256) so a probe can observe it easily;
//   - TMS / TDI output counter bits, forming an identifiable pattern;
//   - TDO inputs are shifted into registers (kept with KEEP so they are not optimized away).
// When connecting the real 12-lane TAP engine, just replace the internal logic of this module; the ports stay the same.

module jtag12_io (
    input  wire clk,          // 100 MHz (PS FCLK_CLK0)
    output wire jtag2_tck,
    output wire jtag2_tms,
    output wire jtag2_tdi,
    input  wire jtag2_tdo,
    output wire jtag3_tck,
    output wire jtag3_tms,
    output wire jtag3_tdi,
    input  wire jtag3_tdo,
    output wire jtag4_tck,
    output wire jtag4_tms,
    output wire jtag4_tdi,
    input  wire jtag4_tdo,
    output wire jtag5_tck,
    output wire jtag5_tms,
    output wire jtag5_tdi,
    input  wire jtag5_tdo,
    output wire jtag6_tck,
    output wire jtag6_tms,
    output wire jtag6_tdi,
    input  wire jtag6_tdo,
    output wire jtag7_tck,
    output wire jtag7_tms,
    output wire jtag7_tdi,
    input  wire jtag7_tdo,
    output wire jtag8_tck,
    output wire jtag8_tms,
    output wire jtag8_tdi,
    input  wire jtag8_tdo,
    output wire jtag9_tck,
    output wire jtag9_tms,
    output wire jtag9_tdi,
    input  wire jtag9_tdo,
    output wire jtag10_tck,
    output wire jtag10_tms,
    output wire jtag10_tdi,
    input  wire jtag10_tdo,
    output wire jtag11_tck,
    output wire jtag11_tms,
    output wire jtag11_tdi,
    input  wire jtag11_tdo,
    output wire jtag12_tck,
    output wire jtag12_tms,
    output wire jtag12_tdi,
    input  wire jtag12_tdo
);

    reg [7:0]  div;
    reg [23:0] pat;
    always @(posedge clk) begin
        div <= div + 8'd1;
        if (div == 8'hFF) pat <= pat + 24'd1;
    end

    wire tck_o = div[7];          // square wave at clk/256
    wire tms_o = pat[0];
    wire tdi_o = pat[1];

    // TDO sampling (KEEP prevents optimization)
    (* KEEP = "TRUE" *) reg [1:0] tdo_sync2;
    always @(posedge clk) tdo_sync2 <= {tdo_sync2[0], jtag2_tdo};
    (* KEEP = "TRUE" *) reg [1:0] tdo_sync3;
    always @(posedge clk) tdo_sync3 <= {tdo_sync3[0], jtag3_tdo};
    (* KEEP = "TRUE" *) reg [1:0] tdo_sync4;
    always @(posedge clk) tdo_sync4 <= {tdo_sync4[0], jtag4_tdo};
    (* KEEP = "TRUE" *) reg [1:0] tdo_sync5;
    always @(posedge clk) tdo_sync5 <= {tdo_sync5[0], jtag5_tdo};
    (* KEEP = "TRUE" *) reg [1:0] tdo_sync6;
    always @(posedge clk) tdo_sync6 <= {tdo_sync6[0], jtag6_tdo};
    (* KEEP = "TRUE" *) reg [1:0] tdo_sync7;
    always @(posedge clk) tdo_sync7 <= {tdo_sync7[0], jtag7_tdo};
    (* KEEP = "TRUE" *) reg [1:0] tdo_sync8;
    always @(posedge clk) tdo_sync8 <= {tdo_sync8[0], jtag8_tdo};
    (* KEEP = "TRUE" *) reg [1:0] tdo_sync9;
    always @(posedge clk) tdo_sync9 <= {tdo_sync9[0], jtag9_tdo};
    (* KEEP = "TRUE" *) reg [1:0] tdo_sync10;
    always @(posedge clk) tdo_sync10 <= {tdo_sync10[0], jtag10_tdo};
    (* KEEP = "TRUE" *) reg [1:0] tdo_sync11;
    always @(posedge clk) tdo_sync11 <= {tdo_sync11[0], jtag11_tdo};
    (* KEEP = "TRUE" *) reg [1:0] tdo_sync12;
    always @(posedge clk) tdo_sync12 <= {tdo_sync12[0], jtag12_tdo};

    assign jtag2_tck = tck_o;
    assign jtag2_tms = tms_o;
    assign jtag2_tdi = tdi_o;
    assign jtag3_tck = tck_o;
    assign jtag3_tms = tms_o;
    assign jtag3_tdi = tdi_o;
    assign jtag4_tck = tck_o;
    assign jtag4_tms = tms_o;
    assign jtag4_tdi = tdi_o;
    assign jtag5_tck = tck_o;
    assign jtag5_tms = tms_o;
    assign jtag5_tdi = tdi_o;
    assign jtag6_tck = tck_o;
    assign jtag6_tms = tms_o;
    assign jtag6_tdi = tdi_o;
    assign jtag7_tck = tck_o;
    assign jtag7_tms = tms_o;
    assign jtag7_tdi = tdi_o;
    assign jtag8_tck = tck_o;
    assign jtag8_tms = tms_o;
    assign jtag8_tdi = tdi_o;
    assign jtag9_tck = tck_o;
    assign jtag9_tms = tms_o;
    assign jtag9_tdi = tdi_o;
    assign jtag10_tck = tck_o;
    assign jtag10_tms = tms_o;
    assign jtag10_tdi = tdi_o;
    assign jtag11_tck = tck_o;
    assign jtag11_tms = tms_o;
    assign jtag11_tdi = tdi_o;
    assign jtag12_tck = tck_o;
    assign jtag12_tms = tms_o;
    assign jtag12_tdi = tdi_o;

endmodule
